window.__votdWeek && window.__votdWeek({"week":"2028-08-28","reading":"Helaman 7–12","days":[{"d":"2028-08-28","ref":"Helaman 7:18","b":"Helaman","c":7,"v":18,"he":"הוּא כִּי הִקְשֵׁיתֶם אֶת־לְבַבְכֶם אַף לֹא תַקְשִׁיבוּ לְקוֹל הָרוֹעֶה הַטּוֹב אַף הִכְעַסְתֶּם אוֹתוֹ עֲלֵיכֶם׃","en":"It is because you have hardened your hearts; yea, ye will not hearken unto the voice of the good shepherd; yea, ye have provoked him to anger against you."},{"d":"2028-08-29","ref":"Helaman 8:15","b":"Helaman","c":8,"v":15,"he":"וְכַאֲשֶׁר כׇּל־הַמַּבִּיטִים אֶל־הַנָּחָשׁ חָיוּ כֵּן כׇּל־הַמַּבִּיטִים אֶל־בֶּן־אֱלֹהִים בֶּאֱמוּנָה בְּרוּחַ נִשְׁבָּרָה יִחְיוּ אַף לְחַיֵּי עוֹלָם׃","en":"And as many as should look upon that serpent should live, even so as many as should look upon the Son of God with faith, having a contrite spirit, might live, even unto that life which is eternal."},{"d":"2028-08-30","ref":"Helaman 8:17","b":"Helaman","c":8,"v":17,"he":"הֵן וְהִנֵּה רָאָה אַבְרָהָם אֶת־בּוֹאוֹ וַיִּמָּלֵא שִׂמְחָה וַיָּגֶל׃","en":"Yea, and behold, Abraham saw of his coming, and was filled with gladness and did rejoice."},{"d":"2028-08-31","ref":"Helaman 11:4","b":"Helaman","c":11,"v":4,"he":"אָנָּא יְהוָה אַל־נָא תִתֵּן לָעָם הַזֶּה לְהִשָּׁמֵד בֶּחָרֶב כִּי־אִם יְהִי־נָא רָעָב בָּאָרֶץ לְעוֹרְרָם לִזְכֹּר אֶת־יְהוָה אֱלֹהֵיהֶם וְאוּלַי יָשׁוּבוּ וְיִפְנוּ אֵלֶיךָ׃","en":"O Lord, do not suffer that this people shall be destroyed by the sword; but O Lord, rather let there be a famine in the land, to stir them up in remembrance of the Lord their God, and perhaps they will repent and turn unto thee."},{"d":"2028-09-01","ref":"Helaman 11:26","b":"Helaman","c":11,"v":26,"he":"וַיְהִי לִתְקוּפַת הַיָּמִים אַף בְּמִסְפַּר שָׁנִים מְעַטּוֹת וַיִּהְיוּ לִגְדוּד שׁוֹדְדִים גָּדוֹל מְאֹד וַיְבַקְּשׁוּ אֶת־כׇּל־מְזִמּוֹת סֵתֶר גָּדִיאַנְטוֹן וַיִּהְיוּ לְשׁוֹדְדֵי גָּדִיאַנְטוֹן׃","en":"And thus in time, yea, even in the space of not many years, they became an exceedingly great band of robbers; and they did search out all the secret plans of Gadianton; and thus they became robbers of Gadianton."},{"d":"2028-09-02","ref":"Helaman 12:1","b":"Helaman","c":12,"v":1,"he":"וְכֵן נוּכַל לִרְאוֹת אֶת־שֶׁקֶר וְגַם אֶת־מְנוֹד לְבַב בְּנֵי־הָאָדָם אַף נִרְאֶה כִּי־יְהוָה בְּחַסְדּוֹ הַגָּדוֹל אֵין־קֵץ יְבָרֵךְ וְיַצְלִיחַ אֶת־הַבּוֹטְחִים בּוֹ׃","en":"And thus we can behold how false, and also the unsteadiness of the hearts of the children of men; yea, we can see that the Lord in his great infinite goodness doth bless and prosper those who put their trust in him."},{"d":"2028-09-03","ref":"Helaman 12:3","b":"Helaman","c":12,"v":3,"he":"וְכֵן נִרְאֶה כִּי אִם־לֹא יְיַסֵּר יְהוָה אֶת־עַמּוֹ בְּצָרוֹת רַבּוֹת אַף אִם־לֹא יִפְקְדֵם בְּמָוֶת וּבְחִתָּה וּבְרָעָב וּבְכׇל־מִינֵי דֶבֶר לֹא יִזְכְּרוּהוּ׃","en":"And thus we see that except the Lord doth chasten his people with many afflictions, yea, except he doth visit them with death and with terror, and with famine and with all manner of pestilence, they will not remember him."}]});
